INSERT INTO public.controls (framework, id, req_de, req_en, meta) VALUES
  ('AIACT', 'AIACT-T-01', 'Ist für jedes bereitgestellte oder genutzte KI-System die Rolle (Anbieter, Betreiber oder beides) festgelegt, einschließlich der Prüfung, ob das System unter eigenem Namen oder eigener Marke in Verkehr gebracht oder in Betrieb genommen wird?', 'Has the role (provider, deployer or both) been assigned for every AI system supplied or used, including a check whether the system is placed on the market or put into service under the organisation''s own name or trademark?', '{"coverage": "teil", "iso_ids": ["a5-21", "a5-22", "c4-05"], "legal_ref": "AI Act Art. 3(3)-(4); Art. 25; Guidelines ¶14-15", "section": "Art. 50 Transparenz · Inventar & Rolle", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-02', 'Ist für Auftragnehmer, Agenturen und Dritte, die das KI-System nutzen, geklärt und dokumentiert, wer es unter eigener Verantwortung für eine eigene berufliche Tätigkeit einsetzt (und damit Betreiber ist) und wer es lediglich im Auftrag und unter Kontrolle der Organisation bedient?', 'For contractors, agencies and third parties using the AI system, has it been settled and recorded who uses it under their own authority for their own professional activity (and is therefore the deployer) and who merely operates it on the organisation''s behalf and under its control?', '{"coverage": "teil", "iso_ids": ["a5-50", "a5-53", "a5-107"], "legal_ref": "AI Act Art. 3(4); Guidelines ¶14; FAQ", "section": "Art. 50 Transparenz · Inventar & Rolle", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-03', 'Ist jedes KI-System den einschlägigen Absätzen des Art. 50 (Abs. 1 Interaktion, Abs. 2 Markierung, Abs. 3 Emotionserkennung/biometrische Kategorisierung, Abs. 4 Deepfakes/Texte) zugeordnet, wobei Mehrfachzuordnungen erfasst sind?', 'Is every AI system mapped to the Article 50 paragraphs it engages (50(1) interaction, 50(2) marking, 50(3) emotion recognition/biometric categorisation, 50(4) deepfakes/text), with multiple mappings per system recorded?', '{"coverage": "teil", "iso_ids": ["a5-21", "a5-78"], "legal_ref": "AI Act Art. 50; Guidelines ¶8", "section": "Art. 50 Transparenz · Inventar & Rolle", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-04', 'Ist für jedes System, das synthetische Audio-, Bild-, Video- oder Textinhalte im Sinne des Art. 50(2) erzeugt, das Datum des Inverkehrbringens dokumentiert und festgestellt, ob es vor dem 2. August 2026 in Verkehr gebracht wurde?', 'For every system generating synthetic audio, image, video or text within Article 50(2), is the placing-on-the-market date documented and has it been established whether it was placed on the market before 2 August 2026?', '{"coverage": "teil", "iso_ids": ["a5-21", "a5-22"], "legal_ref": "AI Act Art. 50(2); Reg. (EU) 2026/1744; Guidelines ¶153-154", "section": "Art. 50 Transparenz · Inventar & Rolle", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-05', 'Wird regelbasierte Automatisierung, die kein KI-System nach Art. 3(1) ist, als außerhalb des Anwendungsbereichs identifiziert und mit Begründung im Inventar geführt?', 'Is rule-based automation that is not an AI system under Article 3(1) identified as out of scope and kept in the inventory with the reason recorded?', '{"coverage": "teil", "iso_ids": ["a5-21", "a5-22"], "legal_ref": "AI Act Art. 3(1); Guidelines ¶30", "section": "Art. 50 Transparenz · Inventar & Rolle", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-07', 'Wird Emotionserkennung am Arbeitsplatz und in Bildungseinrichtungen als verboten behandelt, mit Ausnahme medizinischer oder sicherheitsbezogener Zwecke?', 'Is emotion recognition in the workplace and in education treated as prohibited, save for medical and safety uses?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 5(1)(f)", "section": "Art. 50 Transparenz · Verbote zuerst", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-08', 'Ist biometrische Kategorisierung, die einzeln auf Rasse, politische Meinung, Gewerkschaftszugehörigkeit, religiöse oder weltanschauliche Überzeugung, Sexualleben oder sexuelle Orientierung schließt, als verboten bewertet worden (vorbehaltlich der gesetzlichen Ausnahmen)?', 'Has biometric categorisation that individually deduces race, political opinions, trade-union membership, religious or philosophical beliefs, sex life or sexual orientation been assessed as prohibited, subject to the statutory exceptions?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 5(1)(g)", "section": "Art. 50 Transparenz · Verbote zuerst", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-09', 'Ist jedes KI-System, das für die direkte Interaktion mit natürlichen Personen bestimmt ist, so konzipiert, dass es diese Personen darüber informiert, dass sie mit einer KI interagieren, sofern keine dokumentierte Ausnahme nach Art. 50(1) greift?', 'Is every AI system intended to interact directly with natural persons designed to disclose that fact, unless a documented Article 50(1) exception applies?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(1)", "section": "Art. 50 Transparenz · Art. 50(1) Interaktion", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-10', 'Wird die Offensichtlichkeits-Ausnahme am Maßstab einer angemessen informierten, aufmerksamen und verständigen Person des beabsichtigten und vorhersehbaren Publikums im konkreten Nutzungskontext geprüft und ist festgehalten, dass ein allgemeines öffentliches Bewusstsein über KI die Ausnahme nicht trägt?', 'Is the obviousness exception assessed against a reasonably well-informed, observant and circumspect member of the intended and foreseeable audience in the context of use, and is it recorded that general public awareness that AI exists does not carry the exception?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(1); Guidelines ¶42-45", "section": "Art. 50 Transparenz · Art. 50(1) Interaktion", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-11', 'Ist die Formulierung des KI-Hinweises gegen die fünf unzureichenden Varianten geprüft (nur in AGB, nur maschinenlesbar, bloße Bezeichnung als „Assistent“, generischer seitenweiter Hinweis, reine Technologiebeschreibung)?', 'Has the disclosure wording been checked against the five insufficient formulations (buried in terms and conditions, machine-readable only, labelled merely as an ''assistant'', generic site-wide notice, technology description)?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(1); Guidelines ¶38", "section": "Art. 50 Transparenz · Art. 50(1) Interaktion", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-12', 'Wird der Hinweis angepasst und in zugänglichem Format bereitgestellt, wenn Kinder, ältere Personen oder Menschen mit Behinderungen vorhersehbar zum Publikum gehören?', 'Where children, older users or persons with disabilities are foreseeably in the audience, is the disclosure adapted accordingly and provided in an accessible format?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(1), 50(5); Guidelines ¶32-37", "section": "Art. 50 Transparenz · Art. 50(1) Interaktion", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-13', 'Legen KI-Agenten sowohl ihre künstliche Natur als auch die Person, in deren Auftrag sie handeln, offen – an Schlüsselschritten wie Autorisierung, Validierung und Berichterstattung, bei jeder neuen Interaktion und, wenn das Gegenüber vorab unbekannt ist, in jeder Situation mit vernünftigerweise wahrscheinlicher Interaktion mit einer Person?', 'Do AI agents disclose both their artificial nature and the person on whose behalf they act, at key steps such as authorisation, validation and reporting, at every new interaction and, where the counterpart is unknown in advance, in every situation where interaction with a person is reasonably likely?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(1); Guidelines ¶31", "section": "Art. 50 Transparenz · Art. 50(1) Interaktion", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-14', 'Wird die Strafverfolgungs-Ausnahme nur beansprucht, wenn das System gesetzlich zur Aufdeckung, Verhütung, Ermittlung oder Verfolgung von Straftaten zugelassen ist – nicht für Werkzeuge, mit denen die Öffentlichkeit Straftaten meldet?', 'Is the law-enforcement exception claimed only where the system is authorised by law to detect, prevent, investigate or prosecute criminal offences, and not for tools the public uses to report an offence?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(1); Guidelines ¶46-49", "section": "Art. 50 Transparenz · Art. 50(1) Interaktion", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-15', 'Werden Fälle, in denen ein Mensch der Hauptgesprächspartner ist und die KI nur unterstützt, von Art. 50(1) abgegrenzt und dokumentiert, während Art. 50(4) für die erzeugten Inhalte gesondert geprüft wird?', 'Are cases where a human is the main interlocutor and the AI only assists set aside from Article 50(1) and documented, with Article 50(4) still analysed separately for the generated content?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(1), 50(4); Guidelines ¶30", "section": "Art. 50 Transparenz · Art. 50(1) Interaktion", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-16', 'Ist die Textverarbeitungskette an der Grenze der Standardbearbeitung aufgeteilt (Übersetzung, Formatierung, Rechtschreibung ohne wesentliche inhaltliche Änderung) und sind Zusammenfassen, sinnverändernde Umformulierung, Objekt-/Gesichtsersatz, Stimmklonen und realistische Ereignisfabrikation als darüber hinausgehend klassifiziert?', 'Is the text pipeline split at the standard-editing line (translation, formatting, spelling without substantially altering semantic content), and are summarising, meaning-changing paraphrase, object and face replacement, voice cloning and realistic event fabrication classified as going beyond standard editing?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(2); Guidelines ¶90-92", "section": "Art. 50 Transparenz · Art. 50(2) Markierung", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-17', 'Werden synthetische Ausgaben (Audio, Bild, Video, Text) in maschinenlesbarem Format markiert und als künstlich erzeugt oder manipuliert erkennbar gemacht?', 'Is synthetic output (audio, image, video, text) marked in a machine-readable format and made detectable as artificially generated or manipulated?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(2)", "section": "Art. 50 Transparenz · Art. 50(2) Markierung", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-18', 'Ist die Markierungslösung als wirksam, interoperabel, robust und zuverlässig – soweit technisch machbar – bewertet, auch wenn auf die Lösung des Modellanbieters oder eines Dritten zurückgegriffen wird?', 'Has the marking solution been assessed as effective, interoperable, robust and reliable as far as technically feasible, including where the organisation relies on the model provider''s or a third party''s solution?', '{"coverage": "teil", "iso_ids": ["a5-48", "a5-59"], "legal_ref": "AI Act Art. 50(2)", "section": "Art. 50 Transparenz · Art. 50(2) Markierung", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-19', 'Werden sehr kurze Zeichenketten und Quellcode korrekt als außerhalb des Anwendungsbereichs behandelt, ohne dass damit der übrige Teil der Verarbeitungskette von der Markierungspflicht ausgenommen wird?', 'Are very short strings and source code correctly treated as out of scope, without exempting the rest of the pipeline from the marking duty with them?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(2); Guidelines ¶64-68", "section": "Art. 50 Transparenz · Art. 50(2) Markierung", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-20', 'Sind 3D-Assets, VR/AR/MR-Inhalte, digitale Zwillinge und Agentenausgaben überall dort als markierungspflichtig erfasst, wo die Ausgabe menschlich wahrnehmbar ist (nicht jedoch die zugrunde liegenden technischen Artefakte wie Punktwolken und Meshes)?', 'Are 3-D assets, VR/AR/MR content, digital twins and agent outputs in scope wherever the output is human-perceivable, while the underlying technical artefacts such as point clouds and meshes are not?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(2); Guidelines ¶60-63", "section": "Art. 50 Transparenz · Art. 50(2) Markierung", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-21', 'Sind für Zwischenausgaben in geschlossenen Pipelines alle Bedingungen des ¶87 einzeln geprüft und dokumentiert, und ist festgehalten, dass die Erleichterung die Markierungspflicht für eine veröffentlichte Endausgabe nicht aufhebt?', 'For intermediate outputs in closed pipelines, has every condition in paragraph 87 been assessed individually and recorded, and is it recorded that the relief does not remove the Article 50(2) duty from a published final output within scope?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(2); Guidelines ¶87", "section": "Art. 50 Transparenz · Art. 50(2) Markierung", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-22', 'Wird die Erleichterung für flüchtige Echtzeitinhalte nur in Anspruch genommen, wenn die Markierung technisch nicht machbar ist UND die Nutzer darüber informiert werden, dass der Inhalt KI-generiert ist?', 'Where the relief for ephemeral real-time content is relied on, is marking technically infeasible AND are users told that the content is AI-generated?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(2); Guidelines ¶86-88", "section": "Art. 50 Transparenz · Art. 50(2) Markierung", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-23', 'Ist festgestellt, ob das System Emotionen oder Absichten aus biometrischen Daten ableitet, und wird Sentimentanalyse allein über Transkripte ohne biometrisches Element nicht als Emotionserkennung eingestuft?', 'Has it been established whether the system infers emotions or intentions from biometric data, and is sentiment analysis run over a transcript alone, without that biometric element, not classified as emotion recognition?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 3(39)", "section": "Art. 50 Transparenz · Art. 50(3) Emotionserkennung", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-24', 'Werden die exponierten Personen über den Betrieb des Emotionserkennungs- oder biometrischen Kategorisierungssystems informiert, unabhängig davon, ob es in Echtzeit oder nachträglich läuft?', 'Are the exposed persons informed of the operation of the emotion-recognition or biometric-categorisation system regardless of whether it runs in real time or after the fact?', '{"coverage": "teil", "iso_ids": ["a5-83", "a5-84"], "legal_ref": "AI Act Art. 50(3); Guidelines ¶99-100", "section": "Art. 50 Transparenz · Art. 50(3) Emotionserkennung", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-25', 'Werden die Informationen zur Funktionsweise nach Art. 50(3) bereitgestellt, Zwecke und Weiterverarbeitung nach Datenschutzrecht behandelt, und ist geprüft, ob KI-Act-Hinweis und Datenschutzhinweis kombiniert werden können?', 'Is information on the system''s operation provided as Article 50(3) requires, are purposes and further-processing information handled under data-protection law, and has it been checked whether the AI Act notice and the data-protection notice can be combined?', '{"coverage": "teil", "iso_ids": ["a5-83", "a5-84"], "legal_ref": "AI Act Art. 50(3); Guidelines ¶105-110; DSGVO Art. 13/14", "section": "Art. 50 Transparenz · Art. 50(3) Emotionserkennung", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-26', 'Werden Deepfakes sowie KI-generierte oder manipulierte Texte, die zur Information der Öffentlichkeit über Angelegenheiten von öffentlichem Interesse veröffentlicht werden (ohne redaktionelle Ausnahme), als künstlich erzeugt oder manipuliert offengelegt?', 'Are deepfakes, and AI-generated or manipulated text published to inform the public on matters of public interest where the editorial exception does not apply, disclosed as artificially generated or manipulated?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(4)", "section": "Art. 50 Transparenz · Art. 50(4) Deepfakes/Texte", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-27', 'Werden für jeden synthetischen Inhalt die vier Elemente der Deepfake-Definition nach Art. 3(60) einzeln geprüft und wird dabei der objektive Maßstab des falschen Anscheins ohne Täuschungsabsicht angewendet?', 'For each synthetic item, are the four elements of the deepfake definition in Article 3(60) assessed one by one, applying the objective false-appearance test that requires no intent to deceive?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 3(60); Guidelines ¶113-115", "section": "Art. 50 Transparenz · Art. 50(4) Deepfakes/Texte", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-28', 'Werden Inhalte, die den Naturgesetzen widersprechen und kein Täuschungspotenzial haben, mit dokumentierter Begründung von der Deepfake-Kennzeichnung ausgenommen?', 'Is content that defies the laws of nature or physics and has no potential to mislead excluded from deepfake labelling on the record?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 3(60); Guidelines ¶113", "section": "Art. 50 Transparenz · Art. 50(4) Deepfakes/Texte", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-29', 'Wird bei journalistischen Bildern geprüft, ob die Bearbeitung über die übliche redaktionelle Praxis hinausgeht?', 'For journalistic images, has it been assessed whether the editing goes beyond standard editorial practice?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(4); Guidelines ¶116", "section": "Art. 50 Transparenz · Art. 50(4) Deepfakes/Texte", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-30', 'Ist die sichtbare Deepfake-Kennzeichnung ohne besondere Werkzeuge wahrnehmbar und unabhängig von der maschinenlesbaren Markierung des Anbieters?', 'Is the visible deepfake label perceivable without special tools and independent of the provider''s machine-readable mark?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(4); Guidelines ¶117", "section": "Art. 50 Transparenz · Art. 50(4) Deepfakes/Texte", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-31', 'Wird das abgeschwächte Regime für offensichtlich künstlerische, kreative, satirische oder fiktionale Werke eng ausgelegt, sind rein kommerzielle oder rein informative Inhalte davon ausgeschlossen und wird bei Mischformen der informative Charakter als vorrangig behandelt?', 'Is the attenuated regime for evidently artistic, creative, satirical or fictional works read strictly, is exclusively commercial or purely informative content excluded from it, and where a work mixes informative and creative character is the informative character treated as prevailing?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(4); Guidelines ¶119-123", "section": "Art. 50 Transparenz · Art. 50(4) Deepfakes/Texte", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-32', 'Ist für KI-generierte Texte festgestellt, ob sie veröffentlicht sind – also einer unbestimmten, größeren Zahl nicht verbundener Leser zugänglich – und wird ein Intranet nicht als Veröffentlichung gewertet?', 'For AI-generated text, has it been established whether it is published, that is accessible to an indeterminate, fairly large number of unrelated readers, with an intranet not counting as publication?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(4); Guidelines ¶131", "section": "Art. 50 Transparenz · Art. 50(4) Deepfakes/Texte", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-33', 'Beruht die redaktionelle Ausnahme auf beiden Bedingungen – inhaltliche Prüfung einschließlich Faktencheck und eine Person mit redaktioneller Verantwortung – und ist sichergestellt, dass nach der redaktionellen Freigabe kein wesentlicher KI-Eingriff mehr erfolgt?', 'Does the editorial exception rest on both conditions, substantive review including fact-checking and a person holding editorial responsibility, and is it ensured that no substantive AI intervention occurs after editorial sign-off?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(4); Guidelines ¶133-138", "section": "Art. 50 Transparenz · Art. 50(4) Deepfakes/Texte", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-34', 'Sind bei Berufung auf die redaktionelle Ausnahme Identität und Kontaktdaten der redaktionell verantwortlichen Person öffentlich und leicht auffindbar?', 'Where the editorial exception is relied on, are the identity and contact details of the person holding editorial responsibility publicly and easily findable?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(4); Guidelines ¶138", "section": "Art. 50 Transparenz · Art. 50(4) Deepfakes/Texte", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-35', 'Wird der Hinweis klar und erkennbar spätestens bei der ersten Interaktion oder Exposition bereitgestellt?', 'Is the disclosure provided in a clear and distinguishable manner at the first interaction or exposure at the latest?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(5)", "section": "Art. 50 Transparenz · Art. 50(5) Bereitstellung", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-36', 'Erfolgt der Hinweis bei interaktiven Systemen mindestens einmal zu Beginn jeder Sitzung?', 'For interactive systems, is the disclosure given at least once at the start of every session?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(5); Guidelines ¶141-143", "section": "Art. 50 Transparenz · Art. 50(5) Bereitstellung", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-37', 'Erfolgt der Hinweis für Inhalte nach Art. 50(2) und (4) je Ausgabe und je exponierter Person, einschließlich jeder später exponierten Person?', 'For content under Article 50(2) and (4), is the disclosure provided per output and per exposed person, including every subsequent person exposed?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(5); Guidelines ¶141-143", "section": "Art. 50 Transparenz · Art. 50(5) Bereitstellung", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-38', 'Wird ein zusätzlicher Hinweis bereitgestellt, wenn der Beginn verpasst werden kann (Autoplay, endlose Feeds)?', 'Is additional disclosure provided where the start may be missed, such as autoplay or infinite feeds?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(5); Guidelines ¶141-143", "section": "Art. 50 Transparenz · Art. 50(5) Bereitstellung", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-39', 'Erfüllen die Transparenzhinweise und – bei Hochrisiko-Systemen – das System selbst die anwendbaren Barrierefreiheitsanforderungen (Richtlinien (EU) 2016/2102 und (EU) 2019/882), wobei der Betreiber die Barrierefreiheit in seinem Nutzungskontext verifiziert?', 'Do the transparency disclosures and, for high-risk systems, the system itself meet the applicable accessibility requirements (Directives (EU) 2016/2102 and (EU) 2019/882), with the deployer verifying accessibility in its context of use?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(5); Art. 16(l); Guidelines ¶144; Dir. 2016/2102; Dir. 2019/882", "section": "Art. 50 Transparenz · Art. 50(5) Bereitstellung", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-40', 'Ist für Systeme unter der Übergangsregel der Verordnung (EU) 2026/1744 die Erfüllung der Markierungspflicht nach Art. 50(2) bis zum 2. Dezember 2026 geplant und mit Verantwortlichen und Meilensteinen hinterlegt?', 'For systems covered by the transitional rule in Regulation (EU) 2026/1744, is Article 50(2) compliance planned to be in place by 2 December 2026, with owners and milestones?', '{"coverage": "teil", "iso_ids": ["a5-78", "a5-79"], "legal_ref": "AI Act Art. 50(2); Reg. (EU) 2026/1744; Guidelines ¶153-154", "section": "Art. 50 Transparenz · Fristen & Übergang", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-41', 'Ist dokumentiert, dass Art. 50(1), (3), (4) und (5) seit dem 2. August 2026 gelten und nur die von der Übergangsregel erfassten Bestandssysteme zusätzliche Zeit für Art. 50(2) erhalten?', 'Is it recorded that Articles 50(1), (3), (4) and (5) apply from 2 August 2026, and that only pre-existing systems covered by the transitional rule get extra time for Article 50(2)?', '{"coverage": "teil", "iso_ids": ["a5-78"], "legal_ref": "AI Act Art. 50; Art. 113; Guidelines ¶153-154", "section": "Art. 50 Transparenz · Fristen & Übergang", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-42', 'Werden Texte, die vor dem 2. August 2026 erzeugt, aber danach veröffentlicht werden, gekennzeichnet, und ist dokumentiert, dass vor diesem Datum erzeugte Ausgaben nach Art. 50(2) und Deepfakes nach Art. 50(4) nicht rückwirkend markiert werden müssen (Kennzeichnung ohne unverhältnismäßigen Aufwand empfohlen)?', 'Is text generated before 2 August 2026 but published on or after that date labelled, and is it recorded that outputs under Article 50(2) and deepfakes under Article 50(4) generated before that date need not be marked retroactively (labelling encouraged without disproportionate effort)?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(2), 50(4); Guidelines ¶153-154", "section": "Art. 50 Transparenz · Fristen & Übergang", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-T-43', 'Ist für Markierungs- und Kennzeichnungspflichten nach Art. 50(2), (4) und (5) entschieden, ob der Verhaltenskodex eingehalten oder eine gleichwertig angemessene Alternative dokumentiert und nachgewiesen wird?', 'Where marking or labelling duties under Article 50(2), (4) or (5) apply, has a decision been taken to adhere to the Code of Practice or to document and demonstrate an equivalently adequate alternative?', '{"coverage": "delta", "iso_ids": [], "legal_ref": "AI Act Art. 50(7); Guidelines ¶146-150", "section": "Art. 50 Transparenz · Fristen & Übergang", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-E-01', 'Hat das Unternehmen Maßnahmen ergriffen, die die Entwicklung der KI-Kompetenz seines Personals und anderer in seinem Auftrag mit Betrieb und Nutzung von KI-Systemen befasster Personen unterstützen – abgestimmt auf deren Kenntnisse, Erfahrung und Ausbildung, den Einsatzkontext und die betroffenen Personen (Art. 4 i. d. F. der VO (EU) 2026/1744; ein bestimmtes Kompetenzniveau muss nicht garantiert werden)?', 'Has the organisation taken measures that support the development of AI literacy of its staff and other persons dealing with the operation and use of AI systems on its behalf – tailored to their knowledge, experience and training, the context of use and the persons affected (Article 4 as amended by Regulation (EU) 2026/1744; no particular level of AI literacy has to be guaranteed)?', '{"coverage": "teil", "iso_ids": ["a6-08", "a6-09", "a6-10", "c7-05", "c7-07"], "legal_ref": "AI Act Art. 4 i. d. F. VO (EU) 2026/1744; ISO 42001 Kl. 7.2-7.3, A.4.6", "section": "AI Act Konformität", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-E-02', 'Können betroffene Personen auf Anfrage eine klare und aussagekräftige Erläuterung der Rolle des Hochrisiko-KI-Systems (Anhang III) und der wesentlichen Elemente der sie betreffenden Entscheidung erhalten?', 'Can affected persons obtain, on request, a clear and meaningful explanation of the role of the high-risk (Annex III) AI system and the main elements of the individual decision affecting them?', '{"coverage": "teil", "iso_ids": ["a5-83", "a5-84"], "legal_ref": "AI Act Art. 86; DSGVO Art. 22, Art. 13(2)(f)", "section": "AI Act Konformität", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-E-03', 'Ist ein Weg vorgesehen und kommuniziert, über den Betroffene Beschwerden über das KI-System bei der zuständigen Marktüberwachungsbehörde einreichen können?', 'Is a route provided and communicated through which affected persons can lodge complaints about the AI system with the competent market surveillance authority?', '{"coverage": "teil", "iso_ids": ["a5-11", "a5-84"], "legal_ref": "AI Act Art. 85 (Beschwerderecht der Betroffenen – keine Pflicht des Unternehmens, den Weg zu benennen); ISO 42001 A.8.3", "section": "AI Act Konformität", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-E-04', 'Ist für Anbieter mit Sitz außerhalb der EU ein Bevollmächtigter in der Union durch schriftliches Mandat mit definierten Aufgaben bestellt?', 'For providers established outside the EU, is an EU authorised representative appointed under a written mandate with defined tasks?', '{"coverage": "teil", "iso_ids": ["a5-51", "a5-107"], "legal_ref": "AI Act Art. 22", "section": "AI Act Konformität", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-E-05', 'Prüfen Einführer und Händler vor der Bereitstellung eines Hochrisiko-KI-Systems die in Art. 23 Abs. 1 bzw. Art. 24 Abs. 1 genannten Punkte (u. a. Konformitätsbewertung, technische Dokumentation, CE-Kennzeichnung, EU-Konformitätserklärung, Betriebsanleitung, Bevollmächtigter), und bewahren Einführer die Unterlagen zehn Jahre auf (Art. 23 Abs. 5)?', 'Do importers and distributors verify the items listed in Article 23(1) and Article 24(1) respectively (including conformity assessment, technical documentation, CE marking, EU declaration of conformity, instructions for use, authorised representative) before making a high-risk AI system available, and do importers keep the documents for ten years (Article 23(5))?', '{"coverage": "teil", "iso_ids": ["a5-48", "a5-81"], "legal_ref": "AI Act Art. 23, Art. 24", "section": "AI Act Konformität", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-E-06', 'Besteht ein Prozess, der bei Nichtkonformität eines Hochrisiko-KI-Systems unverzüglich Korrekturmaßnahmen einleitet (Rücknahme, Rückruf, Deaktivierung) und Behörden, Betreiber, Einführer und Händler informiert?', 'Is there a process that takes immediate corrective action (withdrawal, recall, disabling) on non-conformity of a high-risk AI system and informs authorities, deployers, importers and distributors?', '{"coverage": "teil", "iso_ids": ["a5-66", "a5-96", "a5-97", "a5-11"], "legal_ref": "AI Act Art. 20; Art. 16(j)", "section": "AI Act Konformität", "source": "CWS-AI-Checklist"}'::jsonb),
  ('AIACT', 'AIACT-E-07', 'Werden bei Tests unter Realbedingungen oder in einem Reallabor die Bedingungen (Testplan, Registrierung, informierte Einwilligung, Zeitgrenzen, Aufsicht) eingehalten und dokumentiert?', 'Where real-world testing or a regulatory sandbox is used, are the conditions (testing plan, registration, informed consent, time limits, oversight) met and documented?', '{"coverage": "teil", "iso_ids": ["a8-95", "a5-83"], "legal_ref": "AI Act Art. 57-61", "section": "AI Act Konformität", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-R-01', 'Sind KI-Risikokriterien (Akzeptanzschwellen, Risikotoleranz) festgelegt, von der Leitung genehmigt und gepflegt, und steuern sie Entwicklungs-, Bereitstellungs- und Außerbetriebnahme-Entscheidungen?', 'Are AI risk criteria (acceptance thresholds, risk tolerance) established, approved by management and maintained, and do they gate development, deployment and decommissioning decisions?', '{"coverage": "teil", "iso_ids": ["c6-03", "c6-06"], "legal_ref": "ISO 42001 Kl. 6.1.1; NIST GOVERN 1.3", "section": "Risiko-Kern & SoA", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-R-02', 'Ist ein wiederholbarer KI-Risikobewertungsprozess (Konsequenz, Wahrscheinlichkeit, Risikostufe) definiert und dokumentiert, der konsistente, valide und vergleichbare Ergebnisse liefert?', 'Is a repeatable AI risk-assessment process (consequence, likelihood, risk level) defined and documented that produces consistent, valid and comparable results?', '{"coverage": "teil", "iso_ids": ["c6-03", "c6-04", "c6-05", "c6-06", "c6-07"], "legal_ref": "ISO 42001 Kl. 6.1.2; NIST MAP 5.1", "section": "Risiko-Kern & SoA", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-R-03', 'Ist ein KI-Risikobehandlungsprozess definiert, der Behandlungsoptionen auswählt, notwendige Kontrollen bestimmt und diese mit Anhang A der ISO/IEC 42001 abgleicht, damit keine erforderliche Kontrolle ausgelassen wird?', 'Is an AI risk-treatment process defined that selects treatment options, determines necessary controls and reconciles them against ISO/IEC 42001 Annex A so that no necessary control is omitted?', '{"coverage": "teil", "iso_ids": ["c6-08", "c6-09"], "legal_ref": "ISO 42001 Kl. 6.1.3; NIST MANAGE 1.3", "section": "Risiko-Kern & SoA", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-R-04', 'Existiert eine Erklärung zur Anwendbarkeit (SoA) für das AIMS, die je Anhang-A-Kontrolle Anwendbarkeit, Begründung für Ein-/Ausschluss, Umsetzungsstatus und Verantwortlichen enthält und gegen die der Konformitätsstatus berichtet wird?', 'Does a Statement of Applicability (SoA) exist for the AIMS listing, for each Annex A control, applicability, justification for inclusion or exclusion, implementation status and owner, against which conformity status is reported?', '{"coverage": "teil", "iso_ids": ["c6-10"], "legal_ref": "ISO 42001 Kl. 6.1.3 d); Anhang A", "section": "Risiko-Kern & SoA", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-R-05', 'Ist jede Anwendbarkeitsentscheidung der SoA – einschließlich Drittanbieter-KI-Komponenten – auf ein dokumentiertes Ergebnis der Risikobehandlung nach Klausel 6 rückführbar und im Risikoregister und den Auswirkungsbeurteilungen verankert?', 'Is each SoA applicability decision, including for third-party AI components, traceable to a documented Clause 6 risk-treatment outcome and reflected in the risk register and impact assessments?', '{"coverage": "teil", "iso_ids": ["c6-10", "c6-11", "a5-47"], "legal_ref": "ISO 42001 Kl. 6.1.3; A.10.2-A.10.4", "section": "Risiko-Kern & SoA", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-R-06', 'Werden KI-Risikobewertungen in geplanten Intervallen sowie bei wesentlichen Änderungen (Modell, Daten, Zweck, Kontext, Regulierung) erneut durchgeführt und die Auslöser dokumentiert?', 'Are AI risk assessments repeated at planned intervals and on material change (model, data, purpose, context, regulation), with the trigger events documented?', '{"coverage": "teil", "iso_ids": ["c8-05", "c8-06"], "legal_ref": "ISO 42001 Kl. 8.2; NIST MAP 5.1", "section": "Risiko-Kern & SoA", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-R-07', 'Ist der KI-Risikobehandlungsplan umgesetzt, werden die Ergebnisse dokumentiert und wird die Wirksamkeit der umgesetzten Maßnahmen verifiziert?', 'Is the AI risk-treatment plan implemented, are its results documented and is the effectiveness of the implemented measures verified?', '{"coverage": "teil", "iso_ids": ["c8-07", "c8-08"], "legal_ref": "ISO 42001 Kl. 8.3; NIST MANAGE 1.2", "section": "Risiko-Kern & SoA", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-G-01', 'Sind die externen und internen Themen sowie die Rollen der Organisation in Bezug auf KI-Systeme (Anbieter, Produzent, Nutzer) bestimmt und dokumentiert, einschließlich der Prüfung, ob der Klimawandel ein relevantes Thema ist?', 'Are the external and internal issues and the organisation''s roles regarding AI systems (provider, producer, user) determined and documented, including whether climate change is a relevant issue?', '{"coverage": "teil", "iso_ids": ["c4-01", "c4-02", "c4-09"], "legal_ref": "ISO 42001 Kl. 4.1 (inkl. Amd. 1:2024); NIST MAP 1.1", "section": "AIMS Governance & Klauseln", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-G-02', 'Zeigt die oberste Leitung Führung und Verpflichtung für das AIMS, indem sie dessen Anforderungen in die Geschäftsprozesse integriert, Ressourcen freigibt und die Zielerreichung nachverfolgt?', 'Does top management demonstrate leadership and commitment to the AIMS by integrating its requirements into business processes, releasing resources and tracking achievement of outcomes?', '{"coverage": "teil", "iso_ids": ["c5-01", "c5-02", "c5-04"], "legal_ref": "ISO 42001 Kl. 5.1; NIST GOVERN 2.3", "section": "AIMS Governance & Klauseln", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-G-03', 'Wird die dokumentierte Information des AIMS gelenkt (Versionierung, Freigabe, Zugriff, Aufbewahrungsfristen, sichere Entsorgung), einschließlich der Aufzeichnungen zu KI-Systemen?', 'Is AIMS documented information controlled (versioning, approval, access, retention schedule, secure disposal), including records relating to AI systems?', '{"coverage": "teil", "iso_ids": ["c7-11", "c7-12", "c7-13", "c7-14", "c7-16"], "legal_ref": "ISO 42001 Kl. 7.5", "section": "AIMS Governance & Klauseln", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-G-04', 'Werden Änderungen am AIMS geplant und kontrolliert durchgeführt (Zweck, Folgen, Ressourcen- und Rollenauswirkungen, Integrität des AIMS)?', 'Are changes to the AIMS planned and carried out in a controlled manner (purpose, consequences, resource and role impacts, AIMS integrity)?', '{"coverage": "teil", "iso_ids": ["c8-03"], "legal_ref": "ISO 42001 Kl. 6.3", "section": "AIMS Governance & Klauseln", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-G-05', 'Besteht ein Prozess, der nicht inventarisierte („Schatten-“)KI über Beschaffungs-, SaaS-, Netzwerk- und Discovery-Kontrollen erkennt und in den AIMS-Geltungsbereich überführt?', 'Is there a process that detects un-inventoried (''shadow'') AI through procurement, SaaS, network and discovery controls and brings it into AIMS scope?', '{"coverage": "teil", "iso_ids": ["a5-21", "a5-23", "a8-65", "a5-47"], "legal_ref": "ISO 42001 Kl. 4.3; A.4.2; A.9; A.10", "section": "AIMS Governance & Klauseln", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-G-06', 'Sind die zur Erfüllung der AIMS-Anforderungen nötigen Prozesse geplant, umgesetzt und gesteuert, mit Prozesskriterien und dem Nachweis, dass die in 6.1.3 bestimmten Kontrollen implementiert sind?', 'Are the processes needed to meet AIMS requirements planned, implemented and controlled, with process criteria and evidence that the controls determined in 6.1.3 are implemented?', '{"coverage": "teil", "iso_ids": ["c8-01", "c8-02"], "legal_ref": "ISO 42001 Kl. 8.1; NIST MANAGE 1.1", "section": "AIMS Governance & Klauseln", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-G-07', 'Ist bestimmt, wo andere Richtlinien (Datenschutz, ISMS, HR, Qualität) auf KI-Ziele einwirken, und sind die Schnittstellen zwischen KI-Policy und diesen Richtlinien dokumentiert?', 'Has it been determined where other policies (privacy, ISMS, HR, quality) affect AI objectives, and are the interfaces between the AI policy and those policies documented?', '{"coverage": "teil", "iso_ids": ["a5-01", "a5-04"], "legal_ref": "ISO 42001 A.2.3; NIST GOVERN 1.2", "section": "AIMS Governance & Klauseln", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-G-08', 'Wird die KI-Policy in geplanten Intervallen und bei Auslösern (Regulierung, Vorfälle, neue Systeme) überprüft, mit definierter Verantwortung und dokumentiertem Ergebnis?', 'Is the AI policy reviewed at planned intervals and on triggers (regulation, incidents, new systems), with defined responsibility and documented outcome?', '{"coverage": "teil", "iso_ids": ["a5-04", "a5-05"], "legal_ref": "ISO 42001 A.2.4; NIST GOVERN 1.5", "section": "AIMS Governance & Klauseln", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-G-09', 'Existiert ein vertraulicher, repressionsfreier Meldekanal für Bedenken zu KI-Systemen, der operativ funktioniert (Eingang, Triage, zeitnahe Antwort) und dessen Ergebnisse in den Management-Review einfließen?', 'Is there a confidential, retaliation-free channel for reporting concerns about AI systems that operates end-to-end (intake, triage, timely response) and whose outcomes feed into management review?', '{"coverage": "teil", "iso_ids": ["a5-62", "a6-21", "a6-22"], "legal_ref": "ISO 42001 A.3.3; Kl. 9.1; NIST GOVERN 4.3", "section": "AIMS Governance & Klauseln", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-G-10', 'Sind Informationen zu den eingesetzten Tooling-Ressourcen (Algorithmen, Modelle, Frameworks, Werkzeuge) je KI-System dokumentiert?', 'Is information on the tooling resources used (algorithms, models, frameworks, tools) documented per AI system?', '{"coverage": "teil", "iso_ids": ["a5-21", "a8-33"], "legal_ref": "ISO 42001 A.4.4; NIST MAP 2.1", "section": "AIMS Governance & Klauseln", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-G-11', 'Sind System- und Rechenressourcen (Hosting on-prem/Cloud/Edge, Rechenkapazität) je KI-System dokumentiert, einschließlich der Umweltauswirkungen, wo relevant?', 'Are system and compute resources (on-premises/cloud/edge hosting, compute capacity) documented per AI system, including environmental impact where relevant?', '{"coverage": "teil", "iso_ids": ["a8-24", "a8-25", "a5-114"], "legal_ref": "ISO 42001 A.4.5; NIST MEASURE 2.12", "section": "AIMS Governance & Klauseln", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-G-12', 'Sind die Verantwortlichkeiten über den KI-Lebenszyklus zwischen Organisation, Partnern, Lieferanten, Kunden und Dritten zugewiesen und dokumentiert, einschließlich der Rollen Verantwortlicher/Auftragsverarbeiter?', 'Are lifecycle responsibilities allocated and documented among the organisation, partners, suppliers, customers and third parties, including controller/processor roles?', '{"coverage": "teil", "iso_ids": ["a5-50", "a5-51", "a5-52"], "legal_ref": "ISO 42001 A.10.2; AI Act Art. 25; DSGVO Art. 26/28", "section": "AIMS Governance & Klauseln", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-G-13', 'Werden die Erwartungen und Anforderungen der Kunden an verantwortungsvolle KI erfasst und die Grenzen des Einsatzbereichs des KI-Systems an sie kommuniziert?', 'Are customers'' expectations and requirements for responsible AI captured, and are the boundaries of the AI system''s domain of use communicated to them?', '{"coverage": "teil", "iso_ids": ["c4-05", "c7-10"], "legal_ref": "ISO 42001 A.10.4; NIST MEASURE 4.1", "section": "AIMS Governance & Klauseln", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-D-01', 'Sind Datenmanagementprozesse für Entwicklung und Verbesserung von KI-Systemen definiert, dokumentiert und umgesetzt, die Datenschutz, Sicherheit, Repräsentativität, Genauigkeit und Integrität abdecken?', 'Are data management processes for the development and enhancement of AI systems defined, documented and implemented, covering privacy, security, representativeness, accuracy and integrity?', '{"coverage": "teil", "iso_ids": ["a8-109", "a5-24", "a5-83"], "legal_ref": "ISO 42001 A.7.2; AI Act Art. 10; NIST MAP 2.3; DSGVO Art. 5", "section": "Daten für KI-Systeme (A.7)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-D-02', 'Sind Details zu Datenerhebung und -auswahl je Datensatz bestimmt und dokumentiert (Kategorien, Quellen, Demografie, Rechte an personenbezogenen Daten und Urheberrechten, Rechtmäßigkeit von Web-Scraping)?', 'Are details on data acquisition and selection determined and documented per dataset (categories, sources, demographics, rights in personal data and copyright, legitimacy of web scraping)?', '{"coverage": "teil", "iso_ids": ["a5-52", "a5-80", "a5-83"], "legal_ref": "ISO 42001 A.7.3; AI Act Art. 10; DSGVO Art. 6/9/14; EDPB Op. 28/2024", "section": "Daten für KI-Systeme (A.7)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-D-03', 'Besteht ein Prozess, der die Herkunft der Daten über den gesamten Lebenszyklus (Erzeugung, Aktualisierung, Übertragung) nachvollziehbar aufzeichnet?', 'Is there a process that records data provenance across the lifecycle (creation, update, transfer) in a traceable manner?', '{"coverage": "teil", "iso_ids": ["a5-32", "a8-84"], "legal_ref": "ISO 42001 A.7.5; AI Act Art. 10; NIST MAP 2.3", "section": "Daten für KI-Systeme (A.7)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-D-04', 'Sind Kriterien für Datenaufbereitungsmethoden (Bereinigung, Imputation, Normalisierung, Kodierung, Labeling) definiert und dokumentiert?', 'Are criteria for data preparation methods (cleaning, imputation, normalisation, encoding, labelling) defined and documented?', '{"coverage": "teil", "iso_ids": ["a8-109"], "legal_ref": "ISO 42001 A.7.6; NIST MAP 2.3", "section": "Daten für KI-Systeme (A.7)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-D-05', 'Sind Produktions-Feedback und Ground-Truth-Labeling-Pipelines qualitätsgesichert (z. B. Inter-Annotator-Metriken) und gegen Poisoning geschützt, bevor sie in das Nachtraining einfließen?', 'Are production feedback and ground-truth labelling pipelines quality-controlled (e.g. inter-annotator metrics) and guarded against poisoning before feeding retraining?', '{"coverage": "teil", "iso_ids": ["a8-109", "a8-88"], "legal_ref": "ISO 42001 A.7.4/A.7.6; AI Act Art. 10; Google SAIF", "section": "Daten für KI-Systeme (A.7)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-D-06', 'Wird das Modell auf Memorierung und Wiedergabe personenbezogener Daten getestet (Membership-Inference, Extraktion, Prompt-Recall) und ist, wo das Modell als anonym behandelt wird, die Extraktionswahrscheinlichkeit einzelfallbezogen als unerheblich bewertet?', 'Is the model tested for memorisation and regurgitation of personal data (membership inference, extraction, prompt recall) and, where the model is treated as anonymous, is the extraction likelihood assessed as insignificant on a case-by-case basis?', '{"coverage": "teil", "iso_ids": ["a8-39", "a8-96"], "legal_ref": "ISO 42001 A.7.2; DSGVO Art. 5(1)(c)/(f), ErwG 26; EDPB Op. 28/2024", "section": "Daten für KI-Systeme (A.7)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-D-07', 'Werden Betroffenenrechte (Auskunft, Berichtigung, Löschung, Einschränkung, Widerspruch) – soweit technisch machbar – auch gegen Trainingsdaten und das trainierte Modell umgesetzt (Unlearning, Ausgabeunterdrückung, Nachtrainings-Auslöser)?', 'Are data-subject rights (access, rectification, erasure, restriction, objection) applied, where technically feasible, against training data and the trained model (unlearning, output suppression, retraining triggers)?', '{"coverage": "teil", "iso_ids": ["a5-83", "a8-36", "a8-37"], "legal_ref": "ISO 42001 A.7.2; DSGVO Art. 15-21; EDPB Op. 28/2024", "section": "Daten für KI-Systeme (A.7)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-D-08', 'Wird bei Zweitnutzung operativer, Kunden- oder Beschäftigtendaten für Training oder Fine-Tuning eine dokumentierte Vereinbarkeitsprüfung (Zweckbindung) durchgeführt und freigegeben?', 'When operational, customer or employee data is repurposed for training or fine-tuning, is a documented compatibility (purpose-limitation) assessment carried out and approved?', '{"coverage": "teil", "iso_ids": ["a5-83", "a8-108"], "legal_ref": "ISO 42001 A.7.3; DSGVO Art. 5(1)(b), Art. 6(4)", "section": "Daten für KI-Systeme (A.7)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-D-09', 'Sind Aufbewahrungsfristen für Trainingsdatensätze, Prompts/Eingaben, Ausgaben und KI-Logs definiert und mit automatischen Lösch- oder Überprüfungsauslösern technisch durchgesetzt?', 'Are retention schedules defined and technically enforced for training datasets, prompts/inputs, outputs and AI logs, with automated deletion or review triggers?', '{"coverage": "teil", "iso_ids": ["a5-125", "a5-127", "a8-26", "a8-128"], "legal_ref": "ISO 42001 A.7.2; DSGVO Art. 5(1)(e), Art. 17", "section": "Daten für KI-Systeme (A.7)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-D-10', 'Sind datenschutzfreundliche Maßnahmen (Minimierung bei der Aufnahme, Pseudonymisierung, Differential Privacy, datenschutzfreundliche Voreinstellungen) durch Technikgestaltung in den Modell-Lebenszyklus eingebettet?', 'Are privacy-protective measures (minimisation at ingestion, pseudonymisation, differential privacy, privacy-friendly defaults) embedded into the model lifecycle by design and by default?', '{"coverage": "teil", "iso_ids": ["a8-39", "a8-41", "a5-83"], "legal_ref": "ISO 42001 A.7.2; DSGVO Art. 25", "section": "Daten für KI-Systeme (A.7)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-01', 'Werden die Anforderungen für neue KI-Systeme oder wesentliche Erweiterungen (Geschäftszweck, Datenbedarf, Leistungs- und Sicherheitsziele) spezifiziert und dokumentiert?', 'Are requirements for new AI systems or significant enhancements (business purpose, data needs, performance and security objectives) specified and documented?', '{"coverage": "teil", "iso_ids": ["a8-82", "a8-85", "a8-86"], "legal_ref": "ISO 42001 A.6.2.2; AI Act Art. 11; NIST MAP 1.6", "section": "Lebenszyklus & Betrieb (A.6/A.9)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-02', 'Existiert ein Bereitstellungsplan mit Freigabekriterien, und wird vor dem Go-live geprüft und freigegeben, dass alle Anforderungen (Tests, Risiko, Dokumentation) erfüllt sind?', 'Does a deployment plan with release criteria exist, and is it verified and signed off before go-live that all requirements (testing, risk, documentation) are met?', '{"coverage": "teil", "iso_ids": ["a8-105", "a8-106", "a8-95"], "legal_ref": "ISO 42001 A.6.2.5; AI Act Art. 16; NIST MANAGE 1.1", "section": "Lebenszyklus & Betrieb (A.6/A.9)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-03', 'Lösen Änderungen an Modell, Daten, Prompts oder Konfiguration (Nachtraining, Versionswechsel, Fine-Tuning, Challenger-Promotion) vor dem Release eine erneute Risiko- und Auswirkungsbewertung, Re-Validierung mit Offline-/Online-Bewertung sowie eine Freigabe mit Rollback-Plan aus?', 'Do changes to model, data, prompts or configuration (retraining, version updates, fine-tuning, challenger promotion) re-trigger risk and impact assessment, re-validation with offline/online evaluation, and approval with a rollback plan before release?', '{"coverage": "teil", "iso_ids": ["a8-104", "a8-105", "a8-106", "a8-140"], "legal_ref": "ISO 42001 Kl. 6.3, 8.1; A.6.2.5; AI Act Art. 9", "section": "Lebenszyklus & Betrieb (A.6/A.9)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-04', 'Wird das KI-System entsprechend seiner Zweckbestimmung und der begleitenden Gebrauchsanweisung genutzt, und werden Nutzungen außerhalb des Zwecks überwacht und eskaliert?', 'Is the AI system used in accordance with its intended purpose and accompanying instructions for use, with out-of-scope use monitored and escalated?', '{"coverage": "teil", "iso_ids": ["a5-24", "a5-25", "a8-53"], "legal_ref": "ISO 42001 A.9.4; AI Act Art. 26(1); NIST MANAGE 2.4", "section": "Lebenszyklus & Betrieb (A.6/A.9)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-05', 'Ist jede Produktions-Modellversion in einem Register erfasst, das sie mit Trainingsdatenversion, Code-Commit, Hyperparametern, Metriken und Freigabe verknüpft, sodass ein bereitgestelltes Modell reproduzierbar nachgebaut werden kann (Seeds, gepinnte Umgebung)?', 'Is every production model version recorded in a registry linking it to training-data version, code commit, hyperparameters, metrics and approval, so that a deployed model can be reproducibly rebuilt (seeds, pinned environment)?', '{"coverage": "teil", "iso_ids": ["a8-84", "a8-33", "a8-140"], "legal_ref": "ISO 42001 A.6.2.3-A.6.2.5; AI Act Art. 11/12; SLSA", "section": "Lebenszyklus & Betrieb (A.6/A.9)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-06', 'Werden neue Modellversionen über Canary-, Shadow- oder Blue-Green-Verfahren ausgerollt mit automatischem Rollback bei Metrikverschlechterung?', 'Are new model versions released via canary, shadow or blue-green deployment with automated rollback on metric regression?', '{"coverage": "teil", "iso_ids": ["a8-105", "a8-139"], "legal_ref": "ISO 42001 A.6.2.6; Google SAIF", "section": "Lebenszyklus & Betrieb (A.6/A.9)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-07', 'Werden Modellartefakte, Register sowie Feature- und Trainingsdaten mit definierten RTO/RPO gesichert und ist die Wiederherstellung getestet?', 'Are model artefacts, registries and feature/training data backed up with defined RTO/RPO, with restore tested?', '{"coverage": "teil", "iso_ids": ["a8-46", "a8-47", "a8-48", "a5-90"], "legal_ref": "ISO 42001 A.6.2.6; ISO 27001 A.8.13/A.5.30", "section": "Lebenszyklus & Betrieb (A.6/A.9)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-08', 'Sind Produktions-Prompts, Systemanweisungen und Tool-/Agenten-Konfigurationen versioniert und wie Code änderungsgesteuert (Review, Freigabe, Rollback)?', 'Are production prompts, system instructions and tool/agent configurations version-controlled and change-managed like code (review, approval, rollback)?', '{"coverage": "teil", "iso_ids": ["a8-84", "a8-104", "a8-140"], "legal_ref": "ISO 42001 A.6.2.4; ISO 27001 A.8.32; Google SAIF", "section": "Lebenszyklus & Betrieb (A.6/A.9)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-09', 'Erzwingen die ML-Pipelines geschützte Branches, verpflichtendes Peer-Review, signierte Commits, isolierte Build-Runner und ein Freigabe-Gate vor der Promotion in die Produktion?', 'Do the ML pipelines enforce protected branches, mandatory peer review, signed commits, isolated build runners and an approval gate before promotion to production?', '{"coverage": "teil", "iso_ids": ["a8-84", "a8-91", "a8-101", "a8-106"], "legal_ref": "ISO 42001 A.6.2.5; ISO 27001 A.8.25/A.8.32; SLSA L2-L3", "section": "Lebenszyklus & Betrieb (A.6/A.9)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-10', 'Ist der Zugriff auf Modelle, Gewichte, Trainingsdaten und ML-Pipelines rollenbasiert nach dem Least-Privilege-Prinzip geregelt und protokolliert?', 'Is access to models, weights, training data and ML pipelines governed by role-based least privilege and logged?', '{"coverage": "teil", "iso_ids": ["a5-35", "a5-36", "a5-44", "a8-14", "a8-16"], "legal_ref": "ISO 42001 A.6.2.6; ISO 27001 A.5.15/A.8.3; AI Act Art. 15(5); NIST MEASURE 2.7", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-11', 'Sind KI-APIs abgesichert (starke Authentifizierung/OAuth 2.0, Rate-Limiting, Anomalieerkennung, Verschlüsselung in Transit) und werden Zugriffe überwacht?', 'Are AI APIs secured (strong authentication/OAuth 2.0, rate limiting, anomaly detection, encryption in transit) and is access monitored?', '{"coverage": "teil", "iso_ids": ["a8-69", "a8-88", "a8-58"], "legal_ref": "ISO 27001 A.8.9/A.8.20; AI Act Art. 15(5); NIST MEASURE 2.7", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-12', 'Sind KI-spezifische Sicherheitsalarme (Jailbreak-Wellen, Extraktionsmuster, Guardrail-Auslösungen, Poisoning-Indikatoren) in SOC/SIEM integriert und mit Reaktionsregeln hinterlegt?', 'Are AI-specific security alerts (jailbreak surges, extraction patterns, guardrail triggers, poisoning indicators) integrated into SOC/SIEM with response rules?', '{"coverage": "teil", "iso_ids": ["a8-58", "a8-127", "a8-71"], "legal_ref": "ISO 27001 A.8.16; NIST MEASURE 2.7; MITRE ATLAS", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-13', 'Bestehen getestete Schutzmaßnahmen gegen direkte Prompt-Injection und Jailbreaks (Eingabefilterung, System-Prompt-Härtung, Bypass-Tests) für LLM-/GenAI-Anwendungen?', 'Are tested protections against direct prompt injection and jailbreaks (input filtering, system-prompt hardening, bypass testing) in place for LLM/GenAI applications?', '{"coverage": "teil", "iso_ids": ["a8-88", "a8-96"], "legal_ref": "OWASP LLM01:2025; MITRE ATLAS AML.T0051; AI Act Art. 15(5)", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-14', 'Werden nicht vertrauenswürdige Inhalte aus RAG, Tools, Web, Dateien und E-Mails isoliert und gekennzeichnet, sodass sie nicht als Anweisungen interpretiert werden können (Trennung von Daten und Instruktionen)?', 'Is untrusted content from RAG, tools, web, files and email isolated and labelled so that it cannot be interpreted as instructions (data/instruction separation)?', '{"coverage": "teil", "iso_ids": ["a8-88"], "legal_ref": "OWASP LLM01:2025 (indirekt); MITRE ATLAS AML.T0051", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-15', 'Werden alle LLM-Ausgaben als nicht vertrauenswürdig behandelt und vor jeder nachgelagerten Senke (Browser, Shell, Datenbank, Code-Ausführung, Drittsysteme) kontextgerecht bereinigt bzw. kodiert?', 'Are all LLM outputs treated as untrusted and contextually sanitised or encoded before any downstream sink (browser, shell, database, code execution, other systems)?', '{"coverage": "teil", "iso_ids": ["a8-88", "a8-83"], "legal_ref": "OWASP LLM05:2025; MITRE ATLAS AML.T0050; CWE-79/77/94", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-16', 'Erkennen und schwärzen Laufzeit-DLP- bzw. Ausgabefilter personenbezogene Daten, Geheimnisse, Zugangsdaten sowie proprietäre oder Trainingsdaten in Modellantworten?', 'Do runtime DLP or output filters detect and redact personal data, secrets, credentials and proprietary or training data in model responses?', '{"coverage": "teil", "iso_ids": ["a8-42", "a8-45", "a8-13"], "legal_ref": "OWASP LLM02:2025; MITRE ATLAS AML.T0024/T0057; ISO 27001 A.8.12", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-17', 'Werden Token-, Rechen-, Parallelitäts-, Tiefen- und Kostenkontingente je Mandant mit Circuit-Breakern, Agenten-Schleifenlimits und Budgetalarmen durchgesetzt?', 'Are token, compute, concurrency, depth and per-tenant cost quotas enforced with circuit breakers, agent-loop limits and budget alerts?', '{"coverage": "teil", "iso_ids": ["a8-24", "a8-25"], "legal_ref": "OWASP LLM10:2025; MITRE ATLAS AML.T0029; ISO 27017", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-18', 'Wird je KI-System eine maschinenlesbare KI-/ML-Stückliste (z. B. CycloneDX ML-BOM) mit Basismodellen, Datensätzen, Gewichten, Adaptern, Plugins und Bibliotheken samt Herkunft, Lizenz und Schwachstellenverfolgung erzeugt und in der CI aktuell gehalten?', 'Is a machine-readable AI/ML bill of materials (e.g. CycloneDX ML-BOM) generated per AI system, covering base models, datasets, weights, adapters, plugins and libraries with provenance, licence and vulnerability tracking, and kept current in CI?', '{"coverage": "teil", "iso_ids": ["a5-21", "a5-54", "a8-31"], "legal_ref": "OWASP LLM03:2025; CycloneDX ML-BOM; AI Act Art. 11/53; ISO 27001 A.5.21", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-19', 'Werden Modellgewichte und -artefakte kryptografisch signiert mit nachprüfbarer Build-Provenienz, und wird die Signatur beim Laden und am Deployment-Gate verifiziert (unsignierte Artefakte werden abgewiesen)?', 'Are model weights and artefacts cryptographically signed with verifiable build provenance, and is the signature verified at load and at the deployment gate (unsigned artefacts rejected)?', '{"coverage": "teil", "iso_ids": ["a8-93", "a8-77", "a8-106"], "legal_ref": "OWASP LLM03/04:2025; MITRE ATLAS AML.T0018; SLSA/Sigstore; ISO 27001 A.8.31", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-20', 'Werden Trainings-, Fine-Tuning- und RAG-Datenquellen kuratiert, mit Herkunft signiert, in Vertrauensstufen eingeteilt und vor der Aufnahme geprüft (Allow-Lists, Ausreißererkennung)?', 'Are training, fine-tuning and RAG data sources curated, provenance-signed, trust-tiered and gated before ingestion (allow-lists, outlier detection)?', '{"coverage": "teil", "iso_ids": ["a8-88", "a5-32"], "legal_ref": "OWASP LLM04:2025; MITRE ATLAS AML.T0020/T0019; NIST AI 100-2", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-21', 'Werden extraktionsartige Abfragemuster erkannt und gedrosselt, und gelten Egress-DLP und Überwachung für Gewichtsspeicher und große Ausgabevolumina?', 'Are extraction-style query patterns detected and throttled, and do egress DLP and monitoring apply to weight stores and large output volumes?', '{"coverage": "teil", "iso_ids": ["a8-42", "a8-45", "a8-59"], "legal_ref": "MITRE ATLAS AML.T0024.002/T0044; OWASP LLM02:2025; ISO 27001 A.8.12", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-22', 'Sind Embedding- und Vektorspeicher zugriffskontrolliert mit Mandantentrennung und gegen Embedding-Inversion und Retrieval-Poisoning geschützt (Autorisierung und Filterung beim Abruf)?', 'Are embedding and vector stores access-controlled with tenant isolation and protected against embedding inversion and retrieval poisoning (authorisation and filtering at retrieval)?', '{"coverage": "teil", "iso_ids": ["a8-15", "a5-36", "a8-14"], "legal_ref": "OWASP LLM08:2025", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-23', 'Enthält der System-Prompt keine Geheimnisse oder Autorisierungslogik und wird er gegen Extraktion und Leckage getestet?', 'Does the system prompt hold no secrets or authorisation logic, and is it tested against extraction and leakage?', '{"coverage": "teil", "iso_ids": ["a5-104", "a8-96"], "legal_ref": "OWASP LLM07:2025; MITRE ATLAS AML.T0056", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-24', 'Führt eine modellunabhängige Guardrail-Schicht Eingabe- und Ausgabemoderation durch (Toxizität, Jailbreak, Injection, Richtlinien), schließt sie im Fehlerfall sicher (fail-closed) und protokolliert sie Blockierungen?', 'Does a model-independent guardrail layer perform input and output moderation (toxicity, jailbreak, injection, policy), fail closed on error and log blocked events?', '{"coverage": "teil", "iso_ids": ["a8-88", "a8-58"], "legal_ref": "OWASP LLM01/02/05:2025; MITRE ATLAS AML.M0015", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-25', 'Werden Prompts, Completions und Tool-Ein-/Ausgaben vor der Protokollierung von Geheimnissen, Zugangsdaten und personenbezogenen Daten bereinigt, und ist der Zugriff auf Konversationsprotokolle beschränkt?', 'Are prompts, completions and tool I/O redacted of secrets, credentials and personal data before logging, and is access to conversation logs restricted?', '{"coverage": "teil", "iso_ids": ["a8-126", "a8-129", "a5-104"], "legal_ref": "OWASP LLM02:2025; ISO 27001 A.8.12/A.8.15", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-26', 'Arbeiten autonome Agenten nach dem Least-Privilege-Prinzip mit eng begrenzten, explizit freigegebenen Tools (Allow-Lists, Deny-by-Default), wobei jede Fähigkeit einzeln autorisiert ist?', 'Do autonomous agents operate under least privilege with narrowly scoped, explicitly allow-listed tools (deny by default), each capability individually authorised?', '{"coverage": "teil", "iso_ids": ["a5-36", "a5-44", "a8-09"], "legal_ref": "OWASP LLM06:2025; MITRE ATLAS AML.T0053", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-27', 'Erfordern irreversible oder folgenschwere Agentenaktionen (Zahlungen, Löschungen, externe Kommunikation, Code-Merge/Deploy) eine menschliche Freigabe mit vollständigem Audit-Trail?', 'Do irreversible or high-impact agent actions (payments, deletions, external communications, code merge/deploy) require human approval with a full audit trail?', '{"coverage": "teil", "iso_ids": ["a5-08", "a8-140", "a8-56"], "legal_ref": "OWASP LLM06:2025; MITRE ATLAS AML.T0053; ISO 27001 A.5.3; AI Act Art. 14", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-28', 'Läuft modellgenerierter oder agentenausgeführter Code in isolierten, netzwerkbeschränkten, kurzlebigen Sandboxes mit Ressourcenlimits und ohne Zugriff auf Produktionsgeheimnisse?', 'Does model-generated or agent-executed code run in isolated, network-restricted, ephemeral sandboxes with resource limits and no access to production secrets?', '{"coverage": "teil", "iso_ids": ["a8-101", "a8-15", "a5-104"], "legal_ref": "OWASP LLM05/06:2025; MITRE ATLAS AML.T0050; ISO 27001 A.8.31", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-29', 'Werden Drittanbieter- und Basismodelle vor der Einführung risikobewertet (Rechtmäßigkeit der Trainingsdaten, Fähigkeiten, Einschränkungen) und auf Lizenz- und Nutzungsbedingungskonformität geprüft?', 'Are third-party and foundation models risk-assessed before adoption (training-data legality, capabilities, restrictions) and verified for licence and acceptable-use compliance?', '{"coverage": "teil", "iso_ids": ["a5-48", "a5-52", "a5-80", "a5-81"], "legal_ref": "ISO 42001 A.10.3; AI Act Art. 53/55; Google SAIF", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-30', 'Werden ML-Abhängigkeiten, Basis-Images und serialisierte Modellformate auf bekannte Schwachstellen und unsichere Deserialisierung (z. B. Pickle) gescannt, mit Behebungsfristen?', 'Are ML dependencies, base images and serialised model formats scanned for known vulnerabilities and unsafe deserialisation (e.g. pickle), with remediation SLAs?', '{"coverage": "teil", "iso_ids": ["a8-31", "a8-32", "a8-122"], "legal_ref": "ISO 27001 A.8.8; SLSA; Google SAIF", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('ISO42001', 'ISO42001-S-31', 'Werden Pipeline-Zugangsdaten, API-Schlüssel und Signaturschlüssel in einem Tresor mit Rotation und Least Privilege verwaltet, ohne fest codierte Geheimnisse in Code oder Notebooks?', 'Are pipeline credentials, API keys and signing keys vaulted with rotation and least privilege, with no hardcoded secrets in code or notebooks?', '{"coverage": "teil", "iso_ids": ["a5-104", "a8-78", "a8-79", "a8-80"], "legal_ref": "ISO 27001 A.8.24; ISO 27017; Google SAIF", "section": "KI-Sicherheit (LLM/Agenten/Supply Chain)", "source": "CWS-AI-Checklist"}'::jsonb),
  ('NIST_AI_RMF', 'NAIRMF-N-01', 'Besteht ein laufender Prozess, der Änderungen an KI-Gesetzen, -Verordnungen und -Standards (EU AI Act, sektorale Regeln, Leitlinien) überwacht und nachweislich in Kontrollen überführt?', 'Is there an ongoing process that monitors changes in AI laws, regulations and standards (EU AI Act, sectoral rules, guidelines) and demonstrably translates them into control changes?', '{"coverage": "teil", "iso_ids": ["a5-78", "a5-79", "a5-05", "a5-14"], "legal_ref": "NIST GOVERN 1.1; ISO 42001 Kl. 4.2", "section": "NIST AI RMF / GenAI-Profil", "source": "CWS-AI-Checklist"}'::jsonb),
  ('NIST_AI_RMF', 'NAIRMF-N-02', 'Existiert ein dokumentierter TEVV-Plan (Test, Evaluation, Verifikation, Validierung), der Testmethoden, Unabhängigkeit der Tester, Akzeptanzkriterien und Kadenz festlegt und jedes identifizierte Risiko vor der Bereitstellung einem Test zuordnet?', 'Is there a documented TEVV plan (test, evaluation, verification, validation) defining test methods, tester independence, acceptance criteria and cadence, mapping each identified risk to a test before deployment?', '{"coverage": "teil", "iso_ids": ["a8-95", "a5-86", "c9-03"], "legal_ref": "NIST MAP 4; MEASURE 1.1; ISO 42001 A.6.2.4", "section": "NIST AI RMF / GenAI-Profil", "source": "CWS-AI-Checklist"}'::jsonb),
  ('NIST_AI_RMF', 'NAIRMF-N-03', 'Wird die Rate konfabulierter (falscher, aber selbstsicherer) Ausgaben gemessen und durch Grounding, Zitation, Retrieval-Validierung, Konfidenzkennzeichnung und menschliche Verifikation bei folgenschweren Anwendungen begrenzt?', 'Is the rate of confabulated (false-but-confident) outputs measured and mitigated through grounding, citation, retrieval validation, confidence labelling and human verification for high-stakes use?', '{"coverage": "teil", "iso_ids": ["a8-95", "c9-02"], "legal_ref": "NIST MEASURE 2.3, 2.9; NIST AI 600-1 (Confabulation); OWASP LLM09:2025", "section": "NIST AI RMF / GenAI-Profil", "source": "CWS-AI-Checklist"}'::jsonb),
  ('NIST_AI_RMF', 'NAIRMF-N-04', 'Erkennen und blockieren Eingabe-/Ausgabe-Guardrails CBRN-gefährliche, gewaltverherrlichende, hasserfüllte oder obszöne Inhalte sowie die Preisgabe privater Daten und geistigen Eigentums, und ist ihre Wirksamkeit je Schadensklasse per Red-Teaming getestet?', 'Do input/output guardrails detect and block CBRN-dangerous, violent, hateful or obscene content and prevent leakage of private data or intellectual property, with effectiveness red-team tested per harm class?', '{"coverage": "teil", "iso_ids": ["a8-96", "a8-58"], "legal_ref": "NIST MEASURE 2.6/2.7/2.11; NIST AI 600-1 (CBRN, Dangerous, Obscene, IP)", "section": "NIST AI RMF / GenAI-Profil", "source": "CWS-AI-Checklist"}'::jsonb)
INSERT INTO public.risks (risk_id, quelle, text_de, primary_control_framework) VALUES
  ('DR-AIACT-T-01', 'Delta-Pack', 'Risiko bei Nichterfüllung (Rollenzuordnung): Falsche Rollenannahme führt dazu, dass Anbieterpflichten nach Art. 50(1)-(2) oder Betreiberpflichten nach Art. 50(3)-(4) übersehen werden und Bußgelder nach Art. 99 drohen.', 'AIACT'),
  ('DR-AIACT-T-02', 'Delta-Pack', 'Risiko bei Nichterfüllung (Betreiberzuordnung bei Dritten): Ungeklärte Verantwortung führt dazu, dass niemand die Betreiberpflichten (Information Betroffener, Deepfake-Kennzeichnung) wahrnimmt.', 'AIACT'),
  ('DR-AIACT-T-03', 'Delta-Pack', 'Risiko bei Nichterfüllung (Pflichtenzuordnung): Ohne Zuordnung je Absatz bleiben einzelne Transparenzpflichten für ein System unentdeckt und unerfüllt.', 'AIACT'),
  ('DR-AIACT-T-04', 'Delta-Pack', 'Risiko bei Nichterfüllung (Stichtag Inverkehrbringen): Ohne belegtes Datum kann die Übergangsfrist bis 2. Dezember 2026 nicht in Anspruch genommen oder nachgewiesen werden.', 'AIACT'),
  ('DR-AIACT-T-05', 'Delta-Pack', 'Risiko bei Nichterfüllung (Abgrenzung KI-System): Fehlende Begründung der Nicht-Anwendbarkeit ist im Audit nicht nachvollziehbar und kann als Umgehung gewertet werden.', 'AIACT'),
  ('DR-AIACT-T-07', 'Delta-Pack', 'Risiko bei Nichterfüllung (Emotionserkennung Arbeitsplatz/Bildung): Einsatz einer verbotenen Praxis mit höchster Bußgeldstufe und Unterlassungsverfügung.', 'AIACT'),
  ('DR-AIACT-T-08', 'Delta-Pack', 'Risiko bei Nichterfüllung (biometrische Kategorisierung): Verbotene Ableitung besonderer Kategorien; Bußgeld der höchsten Stufe und datenschutzrechtliche Sanktionen.', 'AIACT'),
  ('DR-AIACT-T-09', 'Delta-Pack', 'Risiko bei Nichterfüllung (Interaktionshinweis): Personen werden über die KI-Natur getäuscht; Verstoß gegen Art. 50(1) mit Bußgeld bis 15 Mio. EUR oder 3 % des Umsatzes.', 'AIACT'),
  ('DR-AIACT-T-10', 'Delta-Pack', 'Risiko bei Nichterfüllung (Offensichtlichkeits-Ausnahme): Die Ausnahme wird zu weit ausgelegt und der Interaktionshinweis unterbleibt rechtswidrig.', 'AIACT'),
  ('DR-AIACT-T-11', 'Delta-Pack', 'Risiko bei Nichterfüllung (Hinweisformulierung): Ein formal vorhandener, aber unzureichender Hinweis erfüllt die Pflicht nicht und gilt als Verstoß.', 'AIACT'),
  ('DR-AIACT-T-12', 'Delta-Pack', 'Risiko bei Nichterfüllung (vulnerable Zielgruppen): Der Hinweis erreicht die Betroffenen nicht; Verstoß gegen Art. 50(1) und (5) sowie Barrierefreiheitsrecht.', 'AIACT'),
  ('DR-AIACT-T-13', 'Delta-Pack', 'Risiko bei Nichterfüllung (Agenten-Offenlegung): Autonome Agenten täuschen Gegenüber über Natur und Auftraggeber; Haftung und Bußgeld nach Art. 99.', 'AIACT'),
  ('DR-AIACT-T-14', 'Delta-Pack', 'Risiko bei Nichterfüllung (Strafverfolgungs-Ausnahme): Unberechtigte Berufung auf die Ausnahme; Verstoß gegen die Hinweispflicht.', 'AIACT'),
  ('DR-AIACT-T-15', 'Delta-Pack', 'Risiko bei Nichterfüllung (Abgrenzung Mensch/KI-Unterstützung): Entweder überflüssige Hinweise oder – schlimmer – übersehene Deepfake-/Text-Kennzeichnungspflichten.', 'AIACT'),
  ('DR-AIACT-T-16', 'Delta-Pack', 'Risiko bei Nichterfüllung (Standardbearbeitungsgrenze): Markierungspflichtige Ausgaben werden fälschlich als Standardbearbeitung unmarkiert veröffentlicht.', 'AIACT'),
  ('DR-AIACT-T-17', 'Delta-Pack', 'Risiko bei Nichterfüllung (maschinenlesbare Markierung): Synthetische Inhalte sind nicht erkennbar; Verstoß gegen Art. 50(2) und Beitrag zu Desinformation.', 'AIACT'),
  ('DR-AIACT-T-18', 'Delta-Pack', 'Risiko bei Nichterfüllung (Qualität der Markierung): Leicht entfernbare oder inkompatible Markierungen erfüllen Art. 50(2) nicht; Verantwortung bleibt beim Anbieter.', 'AIACT'),
  ('DR-AIACT-T-19', 'Delta-Pack', 'Risiko bei Nichterfüllung (Ausnahme Kurztext/Code): Übergeneralisierte Ausnahme lässt markierungspflichtige Ausgaben unmarkiert.', 'AIACT'),
  ('DR-AIACT-T-20', 'Delta-Pack', 'Risiko bei Nichterfüllung (immersive Inhalte): Wahrnehmbare synthetische Inhalte in 3D/XR bleiben unmarkiert.', 'AIACT'),
  ('DR-AIACT-T-21', 'Delta-Pack', 'Risiko bei Nichterfüllung (Zwischenausgaben): Die Pipeline-Erleichterung wird auf Endausgaben ausgedehnt und die Markierungspflicht verletzt.', 'AIACT'),
  ('DR-AIACT-T-22', 'Delta-Pack', 'Risiko bei Nichterfüllung (Echtzeit-Erleichterung): Eine der beiden kumulativen Bedingungen fehlt; die Erleichterung greift nicht.', 'AIACT'),
  ('DR-AIACT-T-23', 'Delta-Pack', 'Risiko bei Nichterfüllung (Einstufung Emotionserkennung): Falsche Einstufung führt zu fehlender Information Betroffener oder zu unnötigen Pflichten.', 'AIACT'),
  ('DR-AIACT-T-24', 'Delta-Pack', 'Risiko bei Nichterfüllung (Information Betroffener): Betroffene werden nicht informiert; Verstoß gegen Art. 50(3) und DSGVO-Informationspflichten.', 'AIACT'),
  ('DR-AIACT-T-25', 'Delta-Pack', 'Risiko bei Nichterfüllung (Hinweisinhalt/Kombination): Unvollständige oder widersprüchliche Hinweise nach AI Act und DSGVO.', 'AIACT'),
  ('DR-AIACT-T-26', 'Delta-Pack', 'Risiko bei Nichterfüllung (Deepfake-/Textkennzeichnung): Täuschung der Öffentlichkeit; Verstoß gegen Art. 50(4) mit Bußgeld und Reputationsschaden.', 'AIACT'),
  ('DR-AIACT-T-27', 'Delta-Pack', 'Risiko bei Nichterfüllung (Deepfake-Prüfung): Inhalte werden mangels „Absicht“ fälschlich als Nicht-Deepfake eingestuft und nicht gekennzeichnet.', 'AIACT'),
  ('DR-AIACT-T-28', 'Delta-Pack', 'Risiko bei Nichterfüllung (Ausschluss offensichtlich unrealistischer Inhalte): Undokumentierte Ausschlüsse sind im Audit nicht nachvollziehbar.', 'AIACT'),
  ('DR-AIACT-T-29', 'Delta-Pack', 'Risiko bei Nichterfüllung (journalistische Bildbearbeitung): Manipulierte Bilder gelangen ohne Kennzeichnung in die Berichterstattung.', 'AIACT'),
  ('DR-AIACT-T-30', 'Delta-Pack', 'Risiko bei Nichterfüllung (sichtbare Kennzeichnung): Betreiber verlässt sich auf unsichtbare Anbieter-Markierung; Betreiberpflicht nach Art. 50(4) nicht erfüllt.', 'AIACT'),
  ('DR-AIACT-T-31', 'Delta-Pack', 'Risiko bei Nichterfüllung (Kunst-/Satire-Regime): Zu weite Auslegung entzieht informative Inhalte der Kennzeichnung.', 'AIACT'),
  ('DR-AIACT-T-32', 'Delta-Pack', 'Risiko bei Nichterfüllung (Veröffentlichungsbegriff): Falsche Abgrenzung führt zu fehlender Kennzeichnung öffentlicher Texte.', 'AIACT'),
  ('DR-AIACT-T-33', 'Delta-Pack', 'Risiko bei Nichterfüllung (redaktionelle Ausnahme): Ausnahme entfällt durch nachträglichen KI-Eingriff; Text hätte gekennzeichnet werden müssen.', 'AIACT'),
  ('DR-AIACT-T-34', 'Delta-Pack', 'Risiko bei Nichterfüllung (redaktionelle Verantwortung): Fehlende Auffindbarkeit untergräbt die Glaubwürdigkeit der Ausnahme im Aufsichtsverfahren.', 'AIACT'),
  ('DR-AIACT-T-35', 'Delta-Pack', 'Risiko bei Nichterfüllung (Zeitpunkt/Erkennbarkeit): Verspätete oder versteckte Hinweise erfüllen Art. 50(5) nicht.', 'AIACT'),
  ('DR-AIACT-T-36', 'Delta-Pack', 'Risiko bei Nichterfüllung (Sitzungshinweis): Wiederkehrende Nutzer erhalten keinen Hinweis; Verstoß gegen Art. 50(1) i. V. m. 50(5).', 'AIACT'),
  ('DR-AIACT-T-37', 'Delta-Pack', 'Risiko bei Nichterfüllung (Hinweis je Ausgabe/Person): Weitergegebene Inhalte verlieren ihre Kennzeichnung; spätere Empfänger werden getäuscht.', 'AIACT'),
  ('DR-AIACT-T-38', 'Delta-Pack', 'Risiko bei Nichterfüllung (Autoplay/Feeds): Nutzer sehen den Hinweis nie; Pflicht materiell nicht erfüllt.', 'AIACT'),
  ('DR-AIACT-T-39', 'Delta-Pack', 'Risiko bei Nichterfüllung (Barrierefreiheit): Menschen mit Behinderungen erhalten den Hinweis nicht; Verstoß gegen AI Act und Barrierefreiheitsrecht.', 'AIACT'),
  ('DR-AIACT-T-40', 'Delta-Pack', 'Risiko bei Nichterfüllung (Übergangsfrist): Fristablauf ohne Markierungslösung; ab 2. Dezember 2026 unmittelbarer Verstoß.', 'AIACT'),
  ('DR-AIACT-T-41', 'Delta-Pack', 'Risiko bei Nichterfüllung (Geltungsbeginn): Die Übergangsfrist wird fälschlich auf alle Transparenzpflichten ausgedehnt.', 'AIACT'),
  ('DR-AIACT-T-42', 'Delta-Pack', 'Risiko bei Nichterfüllung (Altinhalte): Nach dem Stichtag veröffentlichte Alt-Texte bleiben unkennzeichnet.', 'AIACT'),
  ('DR-AIACT-T-43', 'Delta-Pack', 'Risiko bei Nichterfüllung (Verhaltenskodex): Ohne Kodex oder dokumentierte Alternative fehlt die Konformitätsvermutung; erhöhte Nachweislast.', 'AIACT'),
  ('DR-AIACT-E-01', 'Delta-Pack', 'Risiko bei Nichterfüllung (KI-Kompetenz Art. 4): Ohne Maßnahmen zur Förderung der KI-Kompetenz drohen Fehlbedienung und blindes Vertrauen in KI-Ausgaben sowie ein Verstoß gegen Art. 4 (anwendbar seit 2. Februar 2025, geändert durch VO (EU) 2026/1744).', 'AIACT'),
  ('DR-AIACT-E-02', 'Delta-Pack', 'Risiko bei Nichterfüllung (Recht auf Erläuterung): Betroffenenrecht nach Art. 86 wird verletzt; Beschwerden und Aufsichtsverfahren.', 'AIACT'),
  ('DR-AIACT-E-03', 'Delta-Pack', 'Risiko bei Nichterfüllung (Beschwerderecht Art. 85): Betroffene kennen ihren Beschwerdeweg nicht; Beschwerden gehen ohne vorherige Klärung an die Behörde; Reputations- und Aufsichtsrisiko.', 'AIACT'),
  ('DR-AIACT-E-04', 'Delta-Pack', 'Risiko bei Nichterfüllung (Bevollmächtigter): Hochrisiko-System darf ohne Bevollmächtigten nicht in der EU bereitgestellt werden.', 'AIACT'),
  ('DR-AIACT-E-05', 'Delta-Pack', 'Risiko bei Nichterfüllung (Einführer-/Händlerpflichten): Nicht-konforme Systeme gelangen in den Markt; eigene Haftung nach Art. 23/24.', 'AIACT'),
  ('DR-AIACT-E-06', 'Delta-Pack', 'Risiko bei Nichterfüllung (Korrekturmaßnahmen Art. 20): Nicht-konformes System bleibt im Einsatz; Informationspflichten verletzt.', 'AIACT'),
  ('DR-AIACT-E-07', 'Delta-Pack', 'Risiko bei Nichterfüllung (Realtests/Reallabor): Tests ohne Einwilligung und Aufsicht verletzen Art. 60/61 und Betroffenenrechte.', 'AIACT'),
  ('DR-ISO42001-R-01', 'Delta-Pack', 'Risiko bei Nichterfüllung (KI-Risikokriterien): Ohne definierte Akzeptanzschwellen sind Risikobewertungen nicht vergleichbar und Freigaben willkürlich.', 'ISO42001'),
  ('DR-ISO42001-R-02', 'Delta-Pack', 'Risiko bei Nichterfüllung (Risikobewertungsprozess 6.1.2): Unsystematische Bewertung übersieht KI-spezifische Risiken (Bias, Robustheit, Missbrauch).', 'ISO42001'),
  ('DR-ISO42001-R-03', 'Delta-Pack', 'Risiko bei Nichterfüllung (Risikobehandlung 6.1.3): Notwendige Anhang-A-Kontrollen werden ausgelassen; Risiken bleiben unbehandelt.', 'ISO42001'),
  ('DR-ISO42001-R-04', 'Delta-Pack', 'Risiko bei Nichterfüllung (SoA): Ohne SoA ist die Zertifizierbarkeit des AIMS nicht gegeben und Ausschlüsse sind nicht begründbar.', 'ISO42001'),
  ('DR-ISO42001-R-05', 'Delta-Pack', 'Risiko bei Nichterfüllung (SoA-Rückverfolgbarkeit): SoA und Risikobehandlung driften auseinander; Auditfeststellung wegen fehlender Begründungskette.', 'ISO42001'),
  ('DR-ISO42001-R-06', 'Delta-Pack', 'Risiko bei Nichterfüllung (operative Risikobewertung 8.2): Veraltete Bewertungen decken neue Risiken nach Modell- oder Datenänderungen nicht ab.', 'ISO42001'),
  ('DR-ISO42001-R-07', 'Delta-Pack', 'Risiko bei Nichterfüllung (Risikobehandlung 8.3): Geplante Maßnahmen bleiben Papier; Restrisiko ist höher als akzeptiert.', 'ISO42001'),
  ('DR-ISO42001-G-01', 'Delta-Pack', 'Risiko bei Nichterfüllung (Kontext 4.1): Das AIMS ist nicht an den tatsächlichen KI-Rollen und Rahmenbedingungen ausgerichtet.', 'ISO42001'),
  ('DR-ISO42001-G-02', 'Delta-Pack', 'Risiko bei Nichterfüllung (Leadership 5.1): Ohne sichtbare Leitungsverpflichtung wird KI-Governance nicht gelebt und unterfinanziert.', 'ISO42001'),
  ('DR-ISO42001-G-03', 'Delta-Pack', 'Risiko bei Nichterfüllung (Dokumentenlenkung 7.5): Nachweise für Behörden und Audits sind unvollständig, veraltet oder nicht auffindbar.', 'ISO42001'),
  ('DR-ISO42001-G-04', 'Delta-Pack', 'Risiko bei Nichterfüllung (Änderungsplanung 6.3): Unkontrollierte AIMS-Änderungen schwächen Kontrollen unbemerkt.', 'ISO42001'),
  ('DR-ISO42001-G-05', 'Delta-Pack', 'Risiko bei Nichterfüllung (Schatten-KI): Ungeprüfte KI-Dienste verarbeiten Daten außerhalb jeder Governance; Datenabfluss und Compliance-Verstöße.', 'ISO42001'),
  ('DR-ISO42001-G-06', 'Delta-Pack', 'Risiko bei Nichterfüllung (Betriebsplanung 8.1): Kontrollen sind beschlossen, aber nicht operativ verankert.', 'ISO42001'),
  ('DR-ISO42001-G-07', 'Delta-Pack', 'Risiko bei Nichterfüllung (Richtlinienabgleich A.2.3): Widersprüchliche Vorgaben zwischen KI-, Datenschutz- und Sicherheitsrichtlinien.', 'ISO42001'),
  ('DR-ISO42001-G-08', 'Delta-Pack', 'Risiko bei Nichterfüllung (Policy-Review A.2.4): Veraltete KI-Policy ignoriert neue Pflichten und Risiken.', 'ISO42001'),
  ('DR-ISO42001-G-09', 'Delta-Pack', 'Risiko bei Nichterfüllung (Meldekanal A.3.3): Beschäftigte melden KI-Risiken aus Angst vor Repressalien nicht; Frühwarnung entfällt.', 'ISO42001'),
  ('DR-ISO42001-G-10', 'Delta-Pack', 'Risiko bei Nichterfüllung (Tooling-Ressourcen A.4.4): Abhängigkeiten von Modellen und Frameworks sind unbekannt; Schwachstellen bleiben unentdeckt.', 'ISO42001'),
  ('DR-ISO42001-G-11', 'Delta-Pack', 'Risiko bei Nichterfüllung (Rechenressourcen A.4.5): Kapazitäts-, Standort- und Nachhaltigkeitsrisiken werden nicht gesteuert.', 'ISO42001'),
  ('DR-ISO42001-G-12', 'Delta-Pack', 'Risiko bei Nichterfüllung (Verantwortungszuweisung A.10.2): Lücken in der Verantwortungskette führen zu unbeaufsichtigten Risiken und Haftungsstreit.', 'ISO42001'),
  ('DR-ISO42001-G-13', 'Delta-Pack', 'Risiko bei Nichterfüllung (Kundenanforderungen A.10.4): Kunden setzen das System außerhalb des vorgesehenen Bereichs ein; Fehlentscheidungen und Haftung.', 'ISO42001'),
  ('DR-ISO42001-D-01', 'Delta-Pack', 'Risiko bei Nichterfüllung (Datenmanagement A.7.2): Unkontrollierte Daten führen zu verzerrten, unsicheren oder rechtswidrigen Modellen.', 'ISO42001'),
  ('DR-ISO42001-D-02', 'Delta-Pack', 'Risiko bei Nichterfüllung (Datenerhebung A.7.3): Rechtswidrig erhobene Trainingsdaten machen das Modell angreifbar; Lösch- und Unterlassungsansprüche.', 'ISO42001'),
  ('DR-ISO42001-D-03', 'Delta-Pack', 'Risiko bei Nichterfüllung (Datenherkunft A.7.5): Ohne Provenienz sind Poisoning, Lizenzverstöße und Datenschutzfragen nicht aufklärbar.', 'ISO42001'),
  ('DR-ISO42001-D-04', 'Delta-Pack', 'Risiko bei Nichterfüllung (Datenaufbereitung A.7.6): Undokumentierte Aufbereitung erzeugt nicht reproduzierbare und verzerrte Modelle.', 'ISO42001'),
  ('DR-ISO42001-D-05', 'Delta-Pack', 'Risiko bei Nichterfüllung (Feedback-/Labelqualität): Manipuliertes oder fehlerhaftes Feedback verschlechtert das Modell schleichend bei jedem Nachtraining.', 'ISO42001'),
  ('DR-ISO42001-D-06', 'Delta-Pack', 'Risiko bei Nichterfüllung (Memorierung): Das Modell gibt personenbezogene Trainingsdaten preis; Datenschutzverletzung nach Art. 33/34 DSGVO.', 'ISO42001'),
  ('DR-ISO42001-D-07', 'Delta-Pack', 'Risiko bei Nichterfüllung (Betroffenenrechte im Modell): Löschansprüche können nicht erfüllt werden; Aufsichtsmaßnahmen bis zum Trainingsverbot.', 'ISO42001'),
  ('DR-ISO42001-D-08', 'Delta-Pack', 'Risiko bei Nichterfüllung (Zweckänderung Training): Zweckwidrige Nutzung von Bestandsdaten für KI-Training ist rechtswidrig und untergräbt Vertrauen.', 'ISO42001'),
  ('DR-ISO42001-D-09', 'Delta-Pack', 'Risiko bei Nichterfüllung (Aufbewahrung KI-Daten): Prompts und Ausgaben mit personenbezogenen Daten werden unbegrenzt gespeichert; Speicherbegrenzung verletzt.', 'ISO42001'),
  ('DR-ISO42001-D-10', 'Delta-Pack', 'Risiko bei Nichterfüllung (Privacy by Design): Personenbezogene Daten fließen ungeschützt in Training und Inferenz; strukturelle DSGVO-Verstöße.', 'ISO42001'),
  ('DR-ISO42001-S-01', 'Delta-Pack', 'Risiko bei Nichterfüllung (Anforderungsspezifikation A.6.2.2): Ohne Anforderungen fehlt der Maßstab für Verifikation, Abnahme und Konformität.', 'ISO42001'),
  ('DR-ISO42001-S-02', 'Delta-Pack', 'Risiko bei Nichterfüllung (Deployment-Gate A.6.2.5): Ungeprüfte Modelle gehen produktiv; Fehler und Verstöße werden erst im Betrieb entdeckt.', 'ISO42001'),
  ('DR-ISO42001-S-03', 'Delta-Pack', 'Risiko bei Nichterfüllung (KI-Änderungsmanagement): Nachtrainierte Modelle verändern Verhalten unbemerkt; Konformität und Sicherheit gehen verloren.', 'ISO42001'),
  ('DR-ISO42001-S-04', 'Delta-Pack', 'Risiko bei Nichterfüllung (bestimmungsgemäße Nutzung A.9.4): Zweckfremde Nutzung macht den Betreiber ggf. zum Anbieter (Art. 25) und erzeugt unbewertete Risiken.', 'ISO42001'),
  ('DR-ISO42001-S-05', 'Delta-Pack', 'Risiko bei Nichterfüllung (Modellregister/Lineage): Vorfälle lassen sich nicht auf Modellversion und Daten zurückführen; Nachweispflicht nicht erfüllbar.', 'ISO42001'),
  ('DR-ISO42001-S-06', 'Delta-Pack', 'Risiko bei Nichterfüllung (progressive Auslieferung): Fehlerhafte Modellversionen treffen alle Nutzer gleichzeitig ohne schnellen Rückweg.', 'ISO42001'),
  ('DR-ISO42001-S-07', 'Delta-Pack', 'Risiko bei Nichterfüllung (Backup/DR für KI): Verlust von Modellen und Trainingsdaten macht KI-Dienste dauerhaft unverfügbar.', 'ISO42001'),
  ('DR-ISO42001-S-08', 'Delta-Pack', 'Risiko bei Nichterfüllung (Prompt-/Konfigurationsmanagement): Unkontrollierte Prompt-Änderungen verändern Systemverhalten ohne Nachweis und Rückweg.', 'ISO42001'),
  ('DR-ISO42001-S-09', 'Delta-Pack', 'Risiko bei Nichterfüllung (Pipeline-Integrität): Manipulierter Code oder Daten gelangen unbemerkt in Produktionsmodelle.', 'ISO42001'),
  ('DR-ISO42001-S-10', 'Delta-Pack', 'Risiko bei Nichterfüllung (Zugriff auf Modelle/Gewichte): Diebstahl oder Manipulation von Modellgewichten und Trainingsdaten.', 'ISO42001'),
  ('DR-ISO42001-S-11', 'Delta-Pack', 'Risiko bei Nichterfüllung (API-Sicherheit): Ungeschützte Modell-Endpunkte ermöglichen Missbrauch, Extraktion und Denial-of-Service.', 'ISO42001'),
  ('DR-ISO42001-S-12', 'Delta-Pack', 'Risiko bei Nichterfüllung (SIEM-Integration): KI-Angriffe bleiben unentdeckt, weil sie außerhalb der Sicherheitsüberwachung stattfinden.', 'ISO42001'),
  ('DR-ISO42001-S-13', 'Delta-Pack', 'Risiko bei Nichterfüllung (Prompt-Injection/Jailbreak): Angreifer umgehen Richtlinien und bringen das Modell zu schädlichen oder vertraulichen Ausgaben.', 'ISO42001'),
  ('DR-ISO42001-S-14', 'Delta-Pack', 'Risiko bei Nichterfüllung (indirekte Prompt-Injection): Versteckte Anweisungen in Dokumenten oder Webseiten kapern das Modell und lösen ungewollte Aktionen aus.', 'ISO42001'),
  ('DR-ISO42001-S-15', 'Delta-Pack', 'Risiko bei Nichterfüllung (Ausgabebehandlung): Modellausgaben führen zu XSS, Command-Injection oder SQL-Injection in nachgelagerten Systemen.', 'ISO42001'),
  ('DR-ISO42001-S-16', 'Delta-Pack', 'Risiko bei Nichterfüllung (Preisgabe sensibler Informationen): Das Modell gibt Geheimnisse oder personenbezogene Daten in Antworten preis.', 'ISO42001'),
  ('DR-ISO42001-S-17', 'Delta-Pack', 'Risiko bei Nichterfüllung (unbegrenzter Verbrauch): Denial-of-Wallet und Dienstausfall durch ressourcenintensive oder endlos laufende Anfragen.', 'ISO42001'),
  ('DR-ISO42001-S-18', 'Delta-Pack', 'Risiko bei Nichterfüllung (AI-BOM): Verwundbare oder lizenzwidrige Komponenten in der KI-Lieferkette bleiben unsichtbar.', 'ISO42001'),
  ('DR-ISO42001-S-19', 'Delta-Pack', 'Risiko bei Nichterfüllung (Modellsignierung): Manipulierte oder mit Backdoors versehene Modelle werden unbemerkt produktiv gesetzt.', 'ISO42001'),
  ('DR-ISO42001-S-20', 'Delta-Pack', 'Risiko bei Nichterfüllung (Data Poisoning): Vergiftete Daten implantieren Backdoors oder Verzerrungen in das Modell.', 'ISO42001'),
  ('DR-ISO42001-S-21', 'Delta-Pack', 'Risiko bei Nichterfüllung (Modellextraktion): Geistiges Eigentum wird durch systematische Abfragen oder Exfiltration der Gewichte gestohlen.', 'ISO42001'),
  ('DR-ISO42001-S-22', 'Delta-Pack', 'Risiko bei Nichterfüllung (Vektor-/RAG-Sicherheit): Mandantenübergreifender Datenabfluss und manipulierte Wissensbasis.', 'ISO42001'),
  ('DR-ISO42001-S-23', 'Delta-Pack', 'Risiko bei Nichterfüllung (System-Prompt): Extrahierte System-Prompts legen Geschäftslogik und Zugangsdaten offen.', 'ISO42001'),
  ('DR-ISO42001-S-24', 'Delta-Pack', 'Risiko bei Nichterfüllung (Guardrail-Schicht): Fehlt die unabhängige Schutzschicht, entscheidet allein das angreifbare Modell über die Einhaltung der Richtlinien.', 'ISO42001'),
  ('DR-ISO42001-S-25', 'Delta-Pack', 'Risiko bei Nichterfüllung (Log-Hygiene): Konversationsprotokolle werden zum Sammelbecken für Geheimnisse und personenbezogene Daten.', 'ISO42001'),
  ('DR-ISO42001-S-26', 'Delta-Pack', 'Risiko bei Nichterfüllung (Agenten-Berechtigungen): Übermäßige Handlungsfreiheit von Agenten führt zu unautorisierten Aktionen und Privilegieneskalation.', 'ISO42001'),
  ('DR-ISO42001-S-27', 'Delta-Pack', 'Risiko bei Nichterfüllung (Human-in-the-Loop für Agenten): Agenten führen irreversible Aktionen ohne Kontrolle aus; finanzieller und rechtlicher Schaden.', 'ISO42001'),
  ('DR-ISO42001-S-28', 'Delta-Pack', 'Risiko bei Nichterfüllung (Sandbox für generierten Code): Ausgeführter Modellcode kompromittiert Produktionssysteme oder exfiltriert Daten.', 'ISO42001'),
  ('DR-ISO42001-S-29', 'Delta-Pack', 'Risiko bei Nichterfüllung (Basismodell-Risiko/Lizenz): Ungeprüfte Basismodelle bringen Rechts-, Sicherheits- und Fähigkeitsrisiken in die eigenen Produkte.', 'ISO42001'),
  ('DR-ISO42001-S-30', 'Delta-Pack', 'Risiko bei Nichterfüllung (ML-Schwachstellenscan): Verwundbare Bibliotheken oder bösartige Modelldateien führen zu Codeausführung beim Laden.', 'ISO42001'),
  ('DR-ISO42001-S-31', 'Delta-Pack', 'Risiko bei Nichterfüllung (Pipeline-Geheimnisse): Geleakte Schlüssel in Notebooks ermöglichen Übernahme der Trainings- und Deployment-Pipeline.', 'ISO42001'),
  ('DR-NAIRMF-N-01', 'Delta-Pack', 'Risiko bei Nichterfüllung (Regulierungs-Monitoring): Neue Pflichten (z. B. Leitlinien, Fristverschiebungen) werden verpasst; Kontrollen veralten.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-N-02', 'Delta-Pack', 'Risiko bei Nichterfüllung (TEVV-Planung): Risiken werden nicht getestet oder nur durch die Entwickler selbst; Freigaben ohne unabhängige Evidenz.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-N-03', 'Delta-Pack', 'Risiko bei Nichterfüllung (Halluzination): Falsche Ausgaben fließen ungeprüft in Entscheidungen; Fehlentscheidungen und Haftung.', 'NIST_AI_RMF'),
  ('DR-NAIRMF-N-04', 'Delta-Pack', 'Risiko bei Nichterfüllung (schädliche Inhalte): Das System erzeugt gefährliche oder rechtswidrige Inhalte; Sicherheits-, Straf- und Reputationsrisiko.', 'NIST_AI_RMF')
