-- ============================================================================
-- 115 neue KI-Kontrollen zum Schließen der Abdeckungslücken (Fable, aus den
-- CWS-Quellchecklisten: AI Act Art. 50 Transparenz (58) + AI Security (170)).
-- AIACT 50 · ISO42001 61 · NIST_AI_RMF 4. Idempotent (ON CONFLICT DO NOTHING).
-- ============================================================================
BEGIN;

-- Dedupe: doppelte Bestandskontrolle entfernen (Fable-Dedupe: = AIACT-A-14.1).
DELETE FROM public.controls WHERE framework='AIACT' AND id='AIACT-A-02.4';  -- REMOVE_EXISTING

ON CONFLICT (framework, id) DO NOTHING;

ON CONFLICT (risk_id) DO NOTHING;

ON CONFLICT (framework, control_id, risk_id) DO NOTHING;

COMMIT;
